import perceivo


@perceivo.start
async def embedded_start(input: perceivo.primitives.StartInput) -> perceivo.primitives.StartOutput:
    """Validate the request and hand it to the embedded child orchestration."""
    request_data = input.request_data or {}

    prompt = request_data.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt is required and must be a non-empty string")
    prompt = prompt.strip()

    # max_length is optional. Reject bool explicitly: bool is a subclass of int
    # in Python, so `isinstance(True, int)` is True and True would become 1.
    max_length = request_data.get("max_length")
    if isinstance(max_length, bool) or not isinstance(max_length, (int, float)):
        max_length = 1000
    max_length = int(max_length)
    if max_length < 1:
        raise ValueError(f"max_length must be positive, got {max_length}")

    perceivo.log.info(
        "Simple embedded orchestration started",
        prompt_length=len(prompt),
        max_length=max_length,
    )

    payload = {
        "prompt": prompt,
        "max_length": max_length,
    }

    # The child orchestration's auto-generated `orchestration` port declares a
    # json input artifact and REQUIRES both prompt and max_length in
    # request_data -- it inherits that contract from the child's own START.
    return perceivo.primitives.StartOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data=payload,
            mime_type="application/json",
        ),
        response_data={
            "prompt": payload["prompt"],
            "max_length": payload["max_length"],
        },
    )

import perceivo


@perceivo.start
async def chat_start(input: perceivo.primitives.StartInput) -> perceivo.primitives.StartOutput:
    """Validate the chat request and fan the parameters out downstream."""
    request_data = input.request_data or {}

    prompt = request_data.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt is required and must be a non-empty string")
    prompt = prompt.strip()

    # max_length is optional. Reject bool explicitly: bool is a subclass of int
    # in Python, so `isinstance(True, int)` is True and True would become 1.
    max_length = request_data.get("max_length")
    if isinstance(max_length, bool) or not isinstance(max_length, (int, float)):
        max_length = 1000
    max_length = int(max_length)
    if max_length < 1:
        raise ValueError(f"max_length must be positive, got {max_length}")

    perceivo.log.info(
        "Simple ChatGPT agent started",
        prompt_length=len(prompt),
        max_length=max_length,
    )

    payload = {
        "prompt": prompt,
        "max_length": max_length,
    }

    # The LLM Request template declares a `json` input artifact, so START emits
    # one. Its own ${prompt} reference resolves from response_data; the artifact
    # is the declared-type carrier that makes the START -> LLM edge type-check.
    return perceivo.primitives.StartOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data=payload,
            mime_type="application/json",
        ),
        response_data={
            "prompt": payload["prompt"],
            "max_length": payload["max_length"],
        },
    )
